 RegulatoryEligibility.Result assess(DomainContext c){return f.runtime.requestContext().run(ctx->{return regulatory.assess(c,f.item,f.lot,f.segment,"SELL",new BigDecimal("100"),"EA");});}
 RegulatoryEligibility.Result assess(){return assess(f.c());}
 String procedure(){String prep=f.evidence(f.map("purpose","independent regulatory conflict fixture"),"REG_PREPARATION");var made=f.run("prepareRegulatoryProcedure",f.map("itemId",f.item,"lotId",f.lot,"physicalScopeId",f.segment,"workId",f.work,"policyId",f.regPolicy,"documentVersionId",prep),null);String proc=f.effects(made).get("procedureId").toString();String submit=f.evidence(f.map("procedureId",proc,"procedureVersionId",f.effects(made).get("procedureVersionId"),"occurredAt",f.now.toString(),"itemId",f.item,"lotId",f.lot,"physicalScopeId",f.segment,"authority","FICTIONAL_TEST_AUTHORITY","policyVersion","fixture-v1"),"REGULATORY_SUBMISSION");f.run("recordSubmission",f.map("procedureId",proc,"occurredAt",f.now.toString(),"occurrenceId",f.occurrence(submit)),1);return proc;}
 String decision(String proc,String state,String start,String q,Instant from,Instant until,String previous){var current=jdbc.queryForMap("SELECT * FROM mulino_trade_regulatory_Procedures WHERE ID=?",proc);var source=f.map("procedureId",proc,"procedureVersionId",current.get("currentversionid"),"decision",state,"action","SELL","startQuantity",start,"quantity",q,"unit","EA","validFrom",from.toString(),"validUntil",until.toString(),"itemId",f.item,"lotId",f.lot,"physicalScopeId",f.segment,"authority","FICTIONAL_TEST_AUTHORITY","policyVersion","fixture-v1");String doc=f.evidence(source,"REGULATORY_DECISION");for(String key:List.of("procedureVersionId","itemId","lotId","physicalScopeId","authority","policyVersion","regulatoryEventId"))source.remove(key);source.put("occurrenceId",f.occurrence(doc));if(previous!=null)source.put("previousVersionId",previous);if(decisionRecordingInstant!=null)f.now=decisionRecordingInstant;var result=f.run("recordRegulatoryDecision",source,((Number)current.get("revision")).intValue());return f.effects(result).get("versionId").toString();}
 String decision(String state,String start,String q){return decision(procedure(),state,start,q,f.now,f.now.plusSeconds(60),null);}
 String occurrenceOf(String decision){return jdbc.queryForObject("SELECT occurrenceId FROM mulino_trade_regulatory_DecisionVersions WHERE ID=?",String.class,decision);}
 void range(RegulatoryEligibility.Result r,String state,String quantity,String... coordinates){assertEquals(state,r.state());assertEquals(0,new BigDecimal(quantity).compareTo(r.eligibleQuantity()));var expected=new ArrayList<RegulatoryEligibility.Range>();for(int i=0;i<coordinates.length;i+=2)expected.add(new RegulatoryEligibility.Range(new BigDecimal(coordinates[i]),new BigDecimal(coordinates[i+1])));assertEquals(expected.size(),r.allowedRanges().size());for(int i=0;i<expected.size();i++){assertEquals(0,expected.get(i).start().compareTo(r.allowedRanges().get(i).start()));assertEquals(0,expected.get(i).end().compareTo(r.allowedRanges().get(i).end()));}}
 @Test void overlappingVerifiedDecisionsRetainSafeRemainderAndBlockConflictedReservation(){String allow=decision("ALLOWED","0","100"),deny=decision("REVOKED","20","20");var result=assess();range(result,"CONFLICT","80","0","20","40","100");assertEquals(Set.of(occurrenceOf(allow),occurrenceOf(deny)),new HashSet<>(result.evidenceRefs()));for(String category:List.of("QC","CUSTOMER","COMMERCIAL"))f.basis(category,"100");var quality=f.runtime.requestContext().run(ctx->{return f.eligibility.assess(f.c(),f.inventory.current(f.c(),"QuantitySegments",f.segment),"SELL",f.customer);});assertEquals("CONFLICT",quality.conditions().stream().filter(x->x.get("condition").equals("REGULATORY")).findFirst().orElseThrow().get("state"));var bad=f.apply(f.envelope("reserveQuantity",f.map("segmentId",f.segment,"salesLineId",f.salesLine,"startQuantity","20","quantity","20","unit","EA"),0));assertEquals("REJECTED",bad.get("outcome"),bad.toString());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM mulino_inventory_SegmentAllocations",Integer.class));var safe=f.apply(f.envelope("reserveQuantity",f.map("segmentId",f.segment,"salesLineId",f.salesLine,"startQuantity","0","quantity","20","unit","EA"),0));assertEquals("APPLIED",safe.get("outcome"),safe.toString());}
 @Test void fullyOverlappingVerifiedDecisionsAreConflictInsteadOfUnknown(){String a=decision("ALLOWED","0","100"),d=decision("REVOKED","0","100");var r=assess();range(r,"CONFLICT","0");assertEquals(Set.of(occurrenceOf(a),occurrenceOf(d)),new HashSet<>(r.evidenceRefs()));}
 @Test void disjointAndTouchingDecisionsAreNotConflict(){decision("ALLOWED","0","40");decision("REVOKED","40","60");range(assess(),"ALLOWED","40","0","40");}
