 @Test void supersededAllowedDecisionIsNotAContradiction(){String proc=procedure(),old=decision(proc,"ALLOWED","0","100",f.now,f.now.plusSeconds(60),null);var frozen=jdbc.queryForMap("SELECT * FROM mulino_trade_regulatory_DecisionVersions WHERE ID=?",old);String next=decision(proc,"REVOKED","0","100",f.now,f.now.plusSeconds(60),old);var r=assess();range(r,"UNKNOWN","0");assertEquals(List.of(occurrenceOf(next)),r.evidenceRefs());assertEquals(frozen,jdbc.queryForMap("SELECT * FROM mulino_trade_regulatory_DecisionVersions WHERE ID=?",old));}
